'use client';

import { useEffect, useRef, useState } from 'react';
import type { FormEvent, FocusEvent, ReactNode } from 'react';
import Link from 'next/link';
import { trackEvent } from '@/lib/analytics';
import BuildersMotionSystem from '@/components/BuildersMotionSystem';

const WHATSAPP_NUMBER = '919871530594';
const CITY_SUGGESTIONS = ['Mumbai/MMR', 'Delhi NCR', 'Gurugram', 'Noida', 'Bengaluru', 'Hyderabad', 'Pune', 'Chennai', 'Ahmedabad', 'Kolkata', 'Jaipur', 'Lucknow', 'Chandigarh', 'Kochi', 'Indore', 'Nagpur', 'Surat'];
const PROJECT_TYPES = ['Residential', 'Commercial', 'Plotted/land', 'Township', 'Mixed-use'];


function Arrow({ className = '' }: { className?: string }) {
  return <svg className={className} viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M4 10h11M10 4l6 6-6 6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" /></svg>;
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return <label className="block text-xs font-medium text-white/65">{label}{children}</label>;
}

export default function BuildersLandingPage() {
  const [name, setName] = useState('');
  const [company, setCompany] = useState('');
  const [city, setCity] = useState('');
  const [projectType, setProjectType] = useState('');
  const [requestType, setRequestType] = useState('both');
  const [whatsapp, setWhatsapp] = useState('');
  const [consent, setConsent] = useState(false);
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [landingCity, setLandingCity] = useState('your city');
  const [ref, setRef] = useState('');
  const [utmSource, setUtmSource] = useState('');
  const [utmMedium, setUtmMedium] = useState('');
  const [utmCampaign, setUtmCampaign] = useState('');
  const [pageUrl, setPageUrl] = useState('https://rkdigitalmedia.in/google-ads-for-builders');
  const [stickyVisible, setStickyVisible] = useState(false);
  const [formStarted, setFormStarted] = useState(false);
  const heroRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const cityParam = (params.get('city') || '').trim().slice(0, 80);
    const safeCity = /^[a-zA-Z0-9 .,'()&/-]+$/.test(cityParam) ? cityParam : '';
    setLandingCity(safeCity || 'your city');
    setRef(params.get('l') || '');
    setUtmSource((params.get('utm_source') || '').slice(0, 120));
    setUtmMedium((params.get('utm_medium') || '').slice(0, 120));
    setUtmCampaign((params.get('utm_campaign') || '').slice(0, 160));
    setPageUrl(window.location.href.slice(0, 2000));
    const hero = heroRef.current;
    if (!hero || typeof IntersectionObserver === 'undefined') return;
    const observer = new IntersectionObserver(([entry]) => setStickyVisible(!entry.isIntersecting), { threshold: 0 });
    observer.observe(hero);
    return () => observer.disconnect();
  }, []);

  const waHref = 'https://wa.me/' + WHATSAPP_NUMBER + '?text=' + encodeURIComponent('Hello Rohit, I would like to discuss Google Ads for my real estate project.');

  function trackWhatsApp(location: string) {
    trackEvent('builders_whatsapp_click', { location });
  }
  function handleFormFocus(event: FocusEvent<HTMLFormElement>) {
    if (!formStarted && event.target instanceof HTMLElement && event.target.matches('input,select,textarea')) {
      setFormStarted(true);
      trackEvent('builders_form_start', { location: 'project_enquiry' });
    }
  }

  async function submitLead(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError('');
    if (!consent) { setError('Please confirm that R.K Digital Media may contact you about this enquiry.'); return; }
    setSubmitting(true);
    try {
      const payload = { name: name.trim(), company: company.trim(), whatsapp: whatsapp.trim(), city, consent, project: company.trim(), email: '', stage: '', budget: '', message: [requestType ? 'Request: ' + ({call:'Strategy call',map:'Free buyer-search map',both:'Strategy call and free buyer-search map'} as Record<string, string>)[requestType] : '', projectType ? 'Project type: ' + projectType : ''].filter(Boolean).join(' | '), ref, utm_source: utmSource, utm_medium: utmMedium, utm_campaign: utmCampaign, page: pageUrl, hp: (event.currentTarget.elements.namedItem('hp') as HTMLInputElement)?.value || '', step: 'initial' };
      const response = await fetch('/api/builders-enquiry', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      const result = await response.json().catch(() => ({}));
      if (!response.ok || result.ok !== true || typeof result.id !== 'string') { const fields = Array.isArray(result.errors) ? result.errors.join(', ') : ''; throw new Error(fields ? 'Please check these fields: ' + fields + '.' : (result.error || 'We could not save your request. Please use WhatsApp instead.')); }
      trackEvent('builders_form_submit', { location: 'project_enquiry', step: 'initial' });
      window.location.assign('/google-ads-for-builders/thanks?' + new URLSearchParams({ l: ref, city: landingCity, id: result.id }).toString());
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong. Please use WhatsApp as a fallback.');
    } finally {
      setSubmitting(false);
    }
  }

  const calUrl = 'https://cal.com/rohit-kumar-seo';
  function trackCta(location: string) { trackEvent('builders_cta_click', { location }); }
  const primary = (location: string, label = 'Book a free strategy call', cls = '') => <a href={calUrl} onClick={() => trackCta(location)} target="_blank" rel="noopener noreferrer" className={cls}>{label}<Arrow className="h-4 w-4"/></a>;
  const whatsappCta = (location: string, label = 'Chat on WhatsApp', cls = '') => <a href={waHref} onClick={() => trackWhatsApp(location)} target="_blank" rel="noopener noreferrer" className={cls}>{label}</a>;
  const primaryClass = 'builders-motion-cta inline-flex items-center justify-center gap-3 rounded-full bg-[#E8282B] px-6 py-4 text-sm font-bold text-white transition hover:bg-[#D02225]';
  const secondaryClass = 'builders-motion-cta inline-flex items-center justify-center gap-3 rounded-full border border-white/20 px-6 py-4 text-sm font-semibold text-white transition hover:border-white/40 hover:bg-white/[.04]';
  return <main className="builders-page bg-[#0D0D0D] text-[#F0EEEE] pb-24 sm:pb-0">
    <BuildersMotionSystem />
    <header className="border-b border-white/[.08] bg-[#101313]"><div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-3 sm:px-6 lg:px-8"><Link href="/" className="flex items-center gap-2.5" aria-label="R.K Digital Media home"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#E8282B] text-sm font-black text-white">RK</span><span className="text-sm font-semibold tracking-wide">R.K DIGITAL MEDIA</span></Link><a href="#project-enquiry" className="text-xs font-semibold text-white/70 underline decoration-[#E8282B] underline-offset-4">Discuss your project</a></div></header>
    <section data-motion-reveal ref={heroRef} className="relative overflow-hidden border-b border-white/[.08]" aria-labelledby="builders-hero-title"><div className="pointer-events-none absolute -right-40 -top-32 h-[32rem] w-[32rem] rounded-full bg-[#E8282B]/[.10] blur-3xl"/><div className="relative mx-auto grid max-w-7xl items-center gap-12 px-4 py-16 sm:px-6 sm:py-20 lg:grid-cols-[1.15fr_.85fr] lg:px-8 lg:py-24"><div><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">Google Ads for property developers and builders{landingCity !== 'your city' ? ' · ' + landingCity : ''}</p><h1 id="builders-hero-title" className="mt-5 max-w-4xl text-4xl font-semibold leading-[1.08] tracking-[-.045em] sm:text-5xl lg:text-6xl">Turn property-search demand into better-qualified enquiries and site visits.</h1><p className="mt-6 max-w-2xl text-base leading-7 text-white/70 sm:text-lg sm:leading-8">I’m Rohit Kumar. I plan and manage Google Ads for residential and commercial projects—helping you reach people actively searching to buy, reduce avoidable spend on irrelevant clicks, and understand which campaigns generate enquiries your sales team can follow up.</p><div className="mt-6 flex flex-wrap gap-2 text-xs"><a href="#certifications" className="rounded-full border border-[#E8282B]/40 bg-[#E8282B]/[.08] px-3.5 py-2 text-white/85">4 Google Skillshop credentials to verify</a><span className="rounded-full border border-white/10 px-3.5 py-2 text-white/65">Direct specialist access</span><span className="rounded-full border border-white/10 px-3.5 py-2 text-white/65">Clear reporting and tracking</span></div><div className="mt-8 flex flex-col gap-3 sm:flex-row sm:flex-wrap">{primary('hero','Discuss your property project',primaryClass)}{whatsappCta('hero','Message Rohit on WhatsApp',secondaryClass)}</div><p className="mt-4 max-w-xl text-xs leading-5 text-white/45">For new launches, ongoing projects or campaigns that need improvement. We’ll discuss your locations, inventory, sales goals, current account and budget before deciding what makes sense.</p><a href="#project-enquiry" className="mt-3 inline-flex text-xs font-medium text-white/60 underline decoration-white/25 underline-offset-4">Not ready for a call? Request a free buyer-search map</a></div><div className="rounded-3xl border border-white/10 bg-[#141414] p-5 sm:p-7"><div className="mb-5 rounded-2xl border border-white/10 bg-[#0D0D0D] p-3.5 sm:p-4" aria-label="Illustration of Google property search leading to a project page and buyer enquiry"><div className="mb-3 flex items-center justify-between gap-3"><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-white/55">How Google Ads works for your project</p><span className="shrink-0 inline-flex items-center gap-1.5 text-[9px] text-white/40"><span className="h-1.5 w-1.5 rounded-full bg-[#E8282B] motion-safe:animate-pulse"></span> Buyer journey</span></div><div className="relative space-y-2.5"><div className="group relative flex items-center gap-3 overflow-hidden rounded-xl border border-white/10 bg-[#151515] p-3 transition-colors duration-300 hover:border-[#E8282B]/40"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-white/[.05] text-white/65"><svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg></span><div className="min-w-0 flex-1"><p className="text-[9px] uppercase tracking-[.12em] text-white/40">1 · Google search</p><p className="mt-1 truncate text-xs font-medium text-white/85">“3 BHK flats in Noida”</p></div><span className="shrink-0 rounded-md border border-white/10 px-2 py-1 text-[9px] text-white/45">Buyer intent</span><span className="pointer-events-none absolute inset-y-0 left-0 w-1 bg-[#E8282B] origin-top scale-y-0 transition-transform duration-300 group-hover:scale-y-100"></span></div><div className="flex h-4 items-center pl-7" aria-hidden="true"><svg viewBox="0 0 260 16" className="h-4 w-full overflow-visible" preserveAspectRatio="none"><path d="M0 8H260" stroke="rgba(255,255,255,.16)" strokeWidth="1.5" strokeDasharray="4 5"/><path d="M0 8H260" stroke="#E8282B" strokeWidth="1.8" strokeDasharray="24 236" strokeLinecap="round"><animate attributeName="stroke-dashoffset" from="260" to="0" dur="3.6s" repeatCount="indefinite"/></path><path d="M254 3l6 5-6 5" stroke="#E8282B" strokeWidth="1.8" fill="none" strokeLinecap="round" strokeLinejoin="round"/></svg></div><div className="group relative flex items-center gap-3 overflow-hidden rounded-xl border border-white/10 bg-[#151515] p-3 transition-colors duration-300 hover:border-[#E8282B]/40"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#E8282B]/10 text-[#FCA5A5]"><svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 21h18M5 21V7l7-4 7 4v14M9 21v-6h6v6M9 9h.01M15 9h.01"/></svg></span><div className="min-w-0 flex-1"><p className="text-[9px] uppercase tracking-[.12em] text-white/40">2 · Your project page</p><p className="mt-1 text-xs font-medium text-white/85">Property details that match</p><p className="mt-1 text-[10px] text-white/40">Location · Price · Key features</p></div><span className="shrink-0 text-[9px] text-[#FCA5A5]">Relevant match</span></div><div className="flex h-4 items-center pl-7" aria-hidden="true"><svg viewBox="0 0 260 16" className="h-4 w-full overflow-visible" preserveAspectRatio="none"><path d="M0 8H260" stroke="rgba(255,255,255,.16)" strokeWidth="1.5" strokeDasharray="4 5"/><path d="M0 8H260" stroke="#E8282B" strokeWidth="1.8" strokeDasharray="24 236" strokeLinecap="round"><animate attributeName="stroke-dashoffset" from="260" to="0" dur="3.6s" begin="1.1s" repeatCount="indefinite"/></path><path d="M254 3l6 5-6 5" stroke="#E8282B" strokeWidth="1.8" fill="none" strokeLinecap="round" strokeLinejoin="round"/></svg></div><div className="group flex items-center gap-3 rounded-xl border border-[#E8282B]/35 bg-[#E8282B]/[.06] p-3 transition duration-300 hover:-translate-y-0.5 hover:bg-[#E8282B]/[.10]"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#E8282B]/15 text-[#FCA5A5]"><svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M21 11.5a8.5 8.5 0 0 1-12.6 7.4L3 20l1.1-4.8A8.5 8.5 0 1 1 21 11.5Z"/><path d="M8.5 11.5h7M12 8v7"/></svg></span><div className="min-w-0 flex-1"><p className="text-[9px] uppercase tracking-[.12em] text-white/45">3 · Buyer enquiry</p><p className="mt-1 text-xs font-semibold text-white/90">Call or enquiry form</p></div><span className="inline-flex shrink-0 items-center gap-1 rounded-full bg-[#E8282B] px-2.5 py-1.5 text-[9px] font-bold text-white"><svg viewBox="0 0 16 16" className="h-3 w-3" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="m3 8 3 3 7-7"/></svg>Sales follow-up</span></div></div><p className="mt-3 text-[10px] leading-4 text-white/35">Illustrative buyer journey—not a live ad or a client result.</p></div><p className="text-[10px] font-semibold uppercase tracking-[.2em] text-[#E8282B]">Built around your project—not a fixed package</p><h2 className="mt-4 text-2xl font-semibold tracking-tight">One clear objective: make ad spend more accountable to sales.</h2><p className="mt-3 text-sm leading-6 text-white/55">The right campaign depends on your project stage, target locations, inventory, competition, sales capacity and budget.</p><div className="mt-6 space-y-4">{[['01','Find buyer intent','Build campaigns around property type, location and purchase-focused searches.'],['02','Protect budget quality','Review search terms, exclude irrelevant demand and improve targeting over time.'],['03','Measure what matters','Track calls and forms, then use lead-quality feedback to guide optimisation.']].map(([n,t,d])=><div key={n} className="flex gap-4 border-t border-white/10 pt-4"><span className="text-xs font-semibold text-[#E8282B]">{n}</span><div><h3 className="text-sm font-semibold">{t}</h3><p className="mt-1 text-sm leading-6 text-white/50">{d}</p></div></div>)}</div><p className="mt-5 rounded-xl border border-white/10 bg-white/[.03] p-4 text-xs leading-5 text-white/55">No one-size-fits-all budget or guaranteed lead count. Recommendations are based on your project economics, market and tracking readiness.</p></div></div></section>
    <section data-motion-reveal className="border-b border-white/[.08] bg-[#0D0D0D]" aria-labelledby="campaign-evidence-title"><div className="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8 lg:py-16"><div className="max-w-3xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">How campaigns are built to grow</p><h2 id="campaign-evidence-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">From search demand to sales-ready enquiries</h2><p className="mt-4 leading-7 text-white/65">The goal is not to buy more clicks. It is to attract people with stronger purchase intent, turn that demand into trackable enquiries, and use sales feedback to improve lead quality over time.</p></div><div className="mt-8 overflow-hidden rounded-3xl border border-white/10 bg-[#141414] p-5 sm:p-8"><div className="flex flex-col gap-7 lg:flex-row lg:items-center"><div className="min-w-0 flex-1"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#E8282B]">The growth pathway</p><h3 className="mt-3 text-xl font-semibold sm:text-2xl">A system for improving lead quality—not just traffic</h3><div className="mt-6 grid gap-3 sm:grid-cols-2">{[{n:'01',title:'Reach the right buyers',body:'Target purchase-led searches, project locations and relevant property intent.'},{n:'02',title:'Convert intent into enquiries',body:'Match ads to a clear landing page and track calls or enquiry forms.'},{n:'03',title:'Identify valuable leads',body:'Where sales feedback is available, separate genuine prospects from missed calls, duplicates and poor-fit enquiries.'},{n:'04',title:'Optimise for business value',body:'Use search-term, conversion and sales feedback to decide what to scale, refine or stop.'}].map((step)=><div key={step.n} className="rounded-xl border border-white/10 bg-[#0D0D0D] p-4"><p className="text-[10px] font-semibold tracking-[.15em] text-[#E8282B]">{step.n} / {step.title.toUpperCase()}</p><p className="mt-2 text-sm leading-6 text-white/60">{step.body}</p></div>)}</div></div><div className="w-full rounded-2xl border border-white/10 bg-[#0D0D0D] p-4 sm:p-5 lg:max-w-[420px]"><p className="text-xs font-semibold text-white/80">Illustrative campaign workflow</p><p className="mt-1 text-xs leading-5 text-white/40">This diagram shows the process to implement and measure. It is not a performance chart or a promise of results.</p><svg className="mt-4 w-full" viewBox="0 0 360 176" role="img" aria-label="Illustrative four-step process: buyer intent, relevant landing page, tracked enquiry, and sales-team feedback; not measured performance data"><path d="M45 34H315M45 88H315M45 142H315" stroke="rgba(255,255,255,.09)" strokeWidth="1" strokeDasharray="3 5"/><path d="M45 34H315" stroke="#E8282B" strokeOpacity=".7" strokeWidth="2" strokeLinecap="round"/><path d="M315 34l-7 -4v8z" fill="#E8282B"/><path d="M45 88H315" stroke="#E8282B" strokeOpacity=".55" strokeWidth="2" strokeLinecap="round"/><path d="M315 88l-7 -4v8z" fill="#E8282B"/><path d="M45 142H315" stroke="#E8282B" strokeOpacity=".4" strokeWidth="2" strokeLinecap="round"/><path d="M315 142l-7 -4v8z" fill="#E8282B"/>{[45,135,225,315].map((x,i)=><g key={i}><circle cx={x} cy={i===0?34:i===1?88:i===2?142:34} r="12" fill="#1A1A1A" stroke="#E8282B" strokeWidth="2"/><text x={x} y={i===0?38:i===1?92:i===2?146:38} textAnchor="middle" fill="#F0EEEE" fontSize="10" fontWeight="600">{i+1}</text></g>)}<text x="45" y="60" textAnchor="middle" fill="rgba(255,255,255,.72)" fontSize="9">Buyer intent</text><text x="135" y="114" textAnchor="middle" fill="rgba(255,255,255,.72)" fontSize="9">Landing page</text><text x="225" y="168" textAnchor="middle" fill="rgba(255,255,255,.72)" fontSize="9">Tracked enquiry</text><text x="315" y="60" textAnchor="middle" fill="rgba(255,255,255,.72)" fontSize="9">Sales feedback</text><path d="M45 34V88H135V142H225V34H315" stroke="#E8282B" strokeWidth="1.5" strokeOpacity=".55" strokeDasharray="3 4" fill="none"/></svg><div className="mt-2 flex items-start gap-3 rounded-xl border border-[#E8282B]/20 bg-[#E8282B]/[.06] p-3"><span className="mt-0.5 text-[#E8282B]" aria-hidden="true">↗</span><p className="text-xs leading-5 text-white/60">The business objective: more relevant conversations for your sales team, with clearer visibility into which campaigns contribute.</p></div></div></div></div><div className="mt-6 grid gap-4 lg:grid-cols-3"><article className="rounded-2xl border border-white/10 bg-[#141414] p-5 sm:p-6"><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-[#E8282B]">Campaign example 01</p><h3 className="mt-3 text-lg font-semibold">Construction search demand</h3><p className="mt-2 text-sm leading-6 text-white/55">A live Search campaign with call-conversion tracking. The optimisation opportunity is to validate call quality and connect tracked calls to genuine enquiries—not treat every recorded action as a sale.</p><div className="mt-5 border-t border-white/10 pt-4"><p className="text-xs font-semibold text-white/75">Business focus</p><p className="mt-2 text-sm leading-6 text-white/50">Capture relevant intent → review call outcomes → prioritise qualified conversations.</p></div></article><article className="rounded-2xl border border-white/10 bg-[#141414] p-5 sm:p-6"><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-[#E8282B]">Campaign example 02</p><h3 className="mt-3 text-lg font-semibold">Interior-solutions enquiries</h3><p className="mt-2 text-sm leading-6 text-white/55">A lead-generation campaign with conversions recorded in Google Ads. The next business-value check is whether enquiries match the service, location and customer profile.</p><div className="mt-5 border-t border-white/10 pt-4"><p className="text-xs font-semibold text-white/75">Business focus</p><p className="mt-2 text-sm leading-6 text-white/50">Match the offer to intent → review enquiry fit → improve lead quality signals.</p></div></article><article className="rounded-2xl border border-white/10 bg-[#141414] p-5 sm:p-6"><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-[#E8282B]">Campaign example 03</p><h3 className="mt-3 text-lg font-semibold">Website-service leads</h3><p className="mt-2 text-sm leading-6 text-white/55">A Search campaign with a small amount of recorded conversion data. It demonstrates why tracking needs context and why decisions should be based on sustained, qualified outcomes.</p><div className="mt-5 border-t border-white/10 pt-4"><p className="text-xs font-semibold text-white/75">Business focus</p><p className="mt-2 text-sm leading-6 text-white/50">Check tracking → understand lead intent → scale only when quality supports it.</p></div></article></div><div className="mt-6 rounded-2xl border border-[#E8282B]/25 bg-[#E8282B]/[.05] p-5 sm:flex sm:items-center sm:justify-between sm:gap-6"><div><h3 className="font-semibold">Want this growth system applied to your property project?</h3><p className="mt-2 max-w-3xl text-sm leading-6 text-white/60">I’ll assess buyer-search intent, target locations, conversion tracking and how your sales team defines a valuable lead. We’ll agree what success should mean for your project before optimising spend.</p></div><div className="mt-4 flex shrink-0 flex-col gap-3 sm:mt-0">{primary('campaign_evidence','Review my project',primaryClass)}{whatsappCta('campaign_evidence','Ask Rohit on WhatsApp',secondaryClass)}</div></div><p className="mt-4 text-xs leading-5 text-white/35">The three campaign examples are anonymised and span different industries; they are not three real-estate developer case studies. The growth curve is illustrative, not a representation of measured historical growth. Reported conversions have not been verified as qualified leads, site visits or sales. Client-derived data should be published only where terms and permissions allow.</p></div></section>
    <section data-motion-reveal className="border-b border-white/[.08] bg-[#101313]" aria-labelledby="sample-review-title"><div className="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8 lg:py-16"><div className="grid gap-8 lg:grid-cols-[.9fr_1.1fr] lg:items-start"><div><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">A practical example</p><h2 id="sample-review-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">What I would review before recommending a campaign</h2><p className="mt-4 leading-7 text-white/60">This is an illustrative review framework, not a claim about a client campaign or its results. The actual priorities depend on your project, account data, budget and sales process.</p><div className="mt-6 rounded-xl border border-[#E8282B]/25 bg-[#E8282B]/[.06] p-4"><p className="text-sm font-semibold text-white">No made-up performance numbers</p><p className="mt-2 text-sm leading-6 text-white/55">I will review the real search terms, spend, enquiries and lead quality available for your project before recommending changes.</p></div><div className="mt-6">{primary('sample_review','Discuss my project and current campaigns',primaryClass)}</div></div><div className="grid gap-3 sm:grid-cols-2">{[{n:'01',title:'Search intent',body:'Separate purchase intent from rentals, resale, jobs, PG and broker-related searches where relevant.'},{n:'02',title:'Location fit',body:'Check whether targeting reflects the project’s real catchment and buyer locations.'},{n:'03',title:'Conversion tracking',body:'Check whether calls and forms are measured correctly and whether duplicate or low-quality conversions distort reports.'},{n:'04',title:'Lead-quality feedback',body:'Connect campaign performance to what the sales team learns from enquiries and site visits, where that data is available.'},{n:'05',title:'Landing-page friction',body:'Review whether the page clearly explains the project, location, offer and next step.'},{n:'06',title:'Prioritised next actions',body:'Recommend fixes by likely impact and feasibility rather than promising a fixed number of leads.'}].map(x=><article key={x.n} className="rounded-2xl border border-white/10 bg-[#141414] p-5"><p className="text-xs font-semibold text-[#E8282B]">{x.n}</p><h3 className="mt-3 text-base font-semibold">{x.title}</h3><p className="mt-2 text-sm leading-6 text-white/55">{x.body}</p></article>)}</div></div></div></section>
    <section data-motion-reveal className="border-b border-white/[.08] bg-[#101313]" aria-labelledby="search-leak-title"><div className="mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8 lg:py-20"><div className="max-w-3xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">Where spend gets wasted</p><h2 id="search-leak-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">Most project budgets leak before a buyer ever clicks</h2><p className="mt-4 leading-7 text-white/60">Broad flat and apartment keywords can also attract people who want to rent, share a PG or find a resale listing. The examples below illustrate search intent—not a forecast of demand. Validate search volumes, locations and match types in Keyword Planner for your target project before setting budgets.</p></div><div className="mt-8 grid gap-4 md:grid-cols-3">{[{city:'Bengaluru',bad:'house for rent bangalore',good:'apartments for sale in bangalore'},{city:'Pune',bad:'flat for rent in pune',good:'apartments for sale in pune'},{city:'Mumbai',bad:'pg in mumbai',good:'new project in mumbai'}].map(x=><article key={x.city} className="rounded-2xl border border-white/10 bg-[#141414] p-5 sm:p-6"><p className="text-sm font-semibold">{x.city}</p><div className="mt-5 border-t border-white/10 pt-4"><p className="text-xs text-white/45">Rental / non-buyer example</p><p className="mt-2 text-sm text-white/80">“{x.bad}”</p></div><div className="mt-5 border-t border-white/10 pt-4"><p className="text-xs text-white/45">Buyer / project example</p><p className="mt-2 text-sm text-white/80">“{x.good}”</p></div><p className="mt-4 text-xs leading-5 text-white/40">Intent examples only; validate volume and relevance for your project.</p></article>)}</div><p className="mt-7 max-w-3xl text-base font-medium leading-7 text-white/85">The job is to prioritise searches that fit the property and exclude irrelevant demand where the data supports it.</p></div></section>
    <section data-motion-reveal className="border-b border-white/[.08]" aria-labelledby="different-title"><div className="mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8 lg:py-20"><div className="max-w-2xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">The way I work</p><h2 id="different-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">What I do differently</h2></div><div className="mt-9 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{[{icon:'target',title:'Buyer searches first',body:'Separate buyer intent from rental, resale and broker searches, then review negatives as search terms change.'},{icon:'map',title:'Your catchment, not the whole city',body:'Target locations based on the project and its realistic buyer catchment.'},{icon:'page',title:'Project-specific landing pages',body:'Use a relevant page for each project. Design and development are scoped separately if needed.'},{icon:'chart',title:'Conversion tracking',body:'Measure calls and form enquiries where technically feasible, then review which conversions are useful.'},{icon:'report',title:'Weekly reporting',body:'See what changed, what was learned and what I recommend next.'},{icon:'target',title:'Clear account ownership',body:'Agree access, account ownership, approvals and reporting expectations before launch.'}].map(x=><article key={x.title} className="rounded-2xl border border-white/10 bg-[#141414] p-5 sm:p-6"><div className="flex h-11 w-11 items-center justify-center rounded-xl border border-[#E8282B]/30 bg-[#E8282B]/[.08] text-[#E8282B]"><FeatureIcon kind={x.icon}/></div><h3 className="mt-5 text-base font-semibold">{x.title}</h3><p className="mt-2 text-sm leading-6 text-white/55">{x.body}</p></article>)}</div></div></section>
    <section data-motion-reveal className="border-b border-white/[.08] bg-[#101313]" aria-labelledby="about-rohit-title"><div className="mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8 lg:py-20"><div className="grid gap-8 lg:grid-cols-[.72fr_1.28fr] lg:items-center lg:gap-14"><div className="mx-auto w-full max-w-sm lg:mx-0"><div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#171717] p-3 shadow-2xl"><div className="absolute left-0 top-8 h-40 w-1 bg-[#E8282B]"/><img src="/images/founder-rohit-kumar.webp" width="640" height="760" loading="lazy" decoding="async" alt="Rohit Kumar, founder of R.K Digital Media" className="aspect-[4/5] w-full rounded-2xl object-cover object-center"/><div className="flex items-center justify-between gap-3 px-2 pb-2 pt-4"><div><p className="font-semibold text-white">Rohit Kumar</p><p className="mt-1 text-xs text-white/55">Founder · R.K Digital Media</p></div><span className="rounded-full border border-[#E8282B]/35 bg-[#E8282B]/[.08] px-3 py-1.5 text-[10px] font-semibold text-white/80">Direct contact</span></div></div><p className="mt-3 text-center text-xs leading-5 text-white/40 lg:text-left">A real person to speak with—not a hand-off to an anonymous account team.</p></div><div className="max-w-3xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">Direct access, clear accountability</p><h2 id="about-rohit-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">You know who is responsible for your Google Ads.</h2><p className="mt-5 leading-7 text-white/70">I’m Rohit Kumar, founder of R.K Digital Media in Greater Noida, Delhi NCR. I work directly with businesses on Google Ads strategy, campaign setup, optimisation and measurement—with a focus here on helping real-estate builders reach people searching for a property to buy.</p><div className="mt-6 grid gap-3 sm:grid-cols-2"><article className="rounded-xl border border-white/10 bg-[#151515] p-4"><p className="text-sm font-semibold text-white">Google Skillshop certified</p><p className="mt-1 text-sm leading-6 text-white/55">Search, Display and AI-Powered Performance Ads credentials, with verification links below.</p></article><article className="rounded-xl border border-white/10 bg-[#151515] p-4"><p className="text-sm font-semibold text-white">Policy-aware campaign setup</p><p className="mt-1 text-sm leading-6 text-white/55">I also run <a href="https://adssuspensionrecovery.com" target="_blank" rel="noopener noreferrer" className="text-white underline decoration-[#E8282B] underline-offset-4">Ads Suspension Recovery</a>, helping businesses address Google Ads suspension issues.</p></article><article className="rounded-xl border border-white/10 bg-[#151515] p-4"><p className="text-sm font-semibold text-white">Clear reporting</p><p className="mt-1 text-sm leading-6 text-white/55">Weekly updates on spend, search terms, measured enquiries, what changed and what I recommend next.</p></article><article className="rounded-xl border border-white/10 bg-[#151515] p-4"><p className="text-sm font-semibold text-white">Transparent ownership</p><p className="mt-1 text-sm leading-6 text-white/55">We agree access, responsibilities, tracking and fees before launch. Google ad spend is paid separately to Google.</p></article></div><p className="mt-5 text-sm leading-6 text-white/50">I won’t promise a fixed number of leads before reviewing your project, market, budget and tracking. The commitment is a clear process, honest reporting and decisions based on the data available.</p><div className="mt-7 flex flex-col gap-3 sm:flex-row sm:flex-wrap">{primary('about_rohit','Book a free project strategy call',primaryClass)}{whatsappCta('about_rohit','Message Rohit on WhatsApp',secondaryClass)}</div></div></div></div></section>
    <CertificationsSection/>

    <section data-motion-reveal className="border-b border-white/[.08] bg-[#101313]" aria-labelledby="audit-preview-title"><div className="mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8 lg:py-20"><div className="grid gap-9 lg:grid-cols-[.8fr_1.2fr] lg:items-start"><div><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">A useful preview of the work</p><h2 id="audit-preview-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">Your campaign should answer more than “How many leads?”</h2><p className="mt-4 leading-7 text-white/60">A property campaign review should help you understand where demand comes from, which clicks are relevant, whether enquiries are being measured correctly, and what to prioritise next. Here is the kind of review structure we can use for your project.</p><div className="mt-6 rounded-2xl border border-[#E8282B]/25 bg-[#E8282B]/[.06] p-5"><p className="text-sm font-semibold text-white">Illustrative audit framework—not a client result</p><p className="mt-2 text-sm leading-6 text-white/60">This preview contains no client data, performance claims or guaranteed outcomes. Findings and recommendations would be based on your project brief and authorised account data.</p></div><div className="mt-6 flex flex-col gap-3 sm:flex-row sm:flex-wrap">{primary('audit_preview','Discuss an audit for my project',primaryClass)}{whatsappCta('audit_preview','Ask a question first',secondaryClass)}</div></div><div className="grid gap-3 sm:grid-cols-2"><article className="rounded-2xl border border-white/10 bg-[#141414] p-5"><p className="text-xs font-semibold text-[#E8282B]">01 / SEARCH QUALITY</p><h3 className="mt-3 text-base font-semibold">Separate buyer intent</h3><p className="mt-2 text-sm leading-6 text-white/55">Review search terms for purchase intent versus rental, resale, jobs, PG or unrelated queries where relevant.</p><div className="mt-4 rounded-lg border border-white/10 bg-[#0D0D0D] p-3"><p className="text-[10px] uppercase tracking-wide text-white/40">Example review item</p><p className="mt-1 text-sm text-white/80">“apartments to buy in [locality]”</p><p className="mt-1 text-xs text-white/45">Compare with irrelevant terms in actual search-term data.</p></div></article><article className="rounded-2xl border border-white/10 bg-[#141414] p-5"><p className="text-xs font-semibold text-[#E8282B]">02 / BUDGET CONTROL</p><h3 className="mt-3 text-base font-semibold">Find avoidable spend</h3><p className="mt-2 text-sm leading-6 text-white/55">Inspect search-term relevance, location settings, campaign overlap and negative keyword opportunities.</p><div className="mt-4 rounded-lg border border-white/10 bg-[#0D0D0D] p-3"><p className="text-[10px] uppercase tracking-wide text-white/40">Output</p><p className="mt-1 text-sm text-white/80">Prioritised exclusions and checks</p><p className="mt-1 text-xs text-white/45">Only after confirming relevance to your offer.</p></div></article><article className="rounded-2xl border border-white/10 bg-[#141414] p-5"><p className="text-xs font-semibold text-[#E8282B]">03 / MEASUREMENT</p><h3 className="mt-3 text-base font-semibold">Check the conversion path</h3><p className="mt-2 text-sm leading-6 text-white/55">Check forms, calls, duplicate conversions, consent and whether reported actions reflect meaningful enquiries.</p><div className="mt-4 rounded-lg border border-white/10 bg-[#0D0D0D] p-3"><p className="text-[10px] uppercase tracking-wide text-white/40">Output</p><p className="mt-1 text-sm text-white/80">Tracking gaps and next steps</p><p className="mt-1 text-xs text-white/45">Based on the tools and access available.</p></div></article><article className="rounded-2xl border border-white/10 bg-[#141414] p-5"><p className="text-xs font-semibold text-[#E8282B]">04 / SALES FEEDBACK</p><h3 className="mt-3 text-base font-semibold">Learn from lead quality</h3><p className="mt-2 text-sm leading-6 text-white/55">Where the sales team can share feedback, connect campaign activity with qualified enquiries and site visits.</p><div className="mt-4 rounded-lg border border-white/10 bg-[#0D0D0D] p-3"><p className="text-[10px] uppercase tracking-wide text-white/40">Output</p><p className="mt-1 text-sm text-white/80">A practical optimisation plan</p><p className="mt-1 text-xs text-white/45">No assumed lead volumes or invented ROI.</p></div></article></div></div></div></section>
    <section data-motion-reveal className="border-b border-white/[.08]" aria-labelledby="working-expectations-title"><div className="mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8 lg:py-20"><div className="max-w-3xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">Trust is built through the process</p><h2 id="working-expectations-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">What you can expect when we work together</h2><p className="mt-4 leading-7 text-white/60">I don’t publish anonymous or unverified testimonials. Instead, here is the working standard I want you to be able to judge me on from the first conversation.</p></div><div className="mt-8 grid gap-4 md:grid-cols-3"><article className="rounded-2xl border border-white/10 bg-[#141414] p-6"><p className="text-2xl font-semibold text-[#E8282B]">01</p><h3 className="mt-4 text-base font-semibold">Clear account access</h3><p className="mt-2 text-sm leading-6 text-white/55">Agree ownership, permissions, budget approval and reporting before changes are made. Your ad spend stays visible in your Google Ads account.</p></article><article className="rounded-2xl border border-white/10 bg-[#141414] p-6"><p className="text-2xl font-semibold text-[#E8282B]">02</p><h3 className="mt-4 text-base font-semibold">Explain the numbers</h3><p className="mt-2 text-sm leading-6 text-white/55">Separate clicks and raw leads from qualified enquiries. Explain what tracking can and cannot tell us, and flag data gaps honestly.</p></article><article className="rounded-2xl border border-white/10 bg-[#141414] p-6"><p className="text-2xl font-semibold text-[#E8282B]">03</p><h3 className="mt-4 text-base font-semibold">Recommendations you can review</h3><p className="mt-2 text-sm leading-6 text-white/55">Get a clear explanation of priorities, trade-offs and proposed changes before major decisions are made.</p></article></div><p className="mt-6 text-xs leading-5 text-white/40">Verified client feedback can be added here when genuine quotes, permission to publish and any necessary context are available.</p></div></section>
    <section data-motion-reveal className="border-b border-white/[.08]" aria-labelledby="first-days-title"><div className="mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8 lg:py-20"><div className="max-w-2xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">A clear starting plan</p><h2 id="first-days-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">What happens after you book</h2></div><ol className="mt-9 grid gap-4 sm:grid-cols-2 lg:grid-cols-5">{[['Discovery','A short call about your project, location, inventory, buyer and sales process.'],['Assessment','Review current campaigns or map initial setup, measurement and landing-page needs.'],['Plan','Agree priorities, responsibilities, scope, budget and tracking readiness before work begins.'],['Optimise','Once live, review search terms, spend and available conversion-quality signals.'],['Review','Receive clear reporting and agreed next steps based on the data available.']].map(([time,desc])=><li key={time} className="rounded-2xl border border-white/10 bg-[#141414] p-5"><p className="text-sm font-semibold text-[#E8282B]">{time}</p><p className="mt-3 text-sm leading-6 text-white/65">{desc}</p></li>)}</ol></div></section>
    <section data-motion-reveal className="border-y border-white/[.08] bg-[#101313]" aria-labelledby="faq-title"><div className="mx-auto max-w-5xl px-4 py-16 sm:px-6 lg:px-8 lg:py-20"><div className="max-w-2xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">Straight answers</p><h2 id="faq-title" className="mt-4 text-3xl font-semibold tracking-[-.035em] sm:text-4xl">Questions builders ask before getting started</h2></div><div className="mt-8 divide-y divide-white/10">{[['Can you guarantee a number of leads?','No honest advertiser can promise that. I commit to clean tracking, blocking wasted clicks, and a weekly report you can read in two minutes.'],['How is your management fee decided?','The fee is customised to the actual scope: monthly ad spend, number of projects and locations, campaign complexity, tracking needs, reporting requirements and any additional landing-page or integration work. Google ad spend is paid to Google separately. I will confirm the scope and fee before any work begins.'], ['Who pays Google?','Your ad spend is paid to Google separately from the management fee. You should retain clear visibility into spend and account access.'], ['We already run ads or use an agency. Can you review it?','Yes. We can discuss an account review, subject to appropriate access and permission. I will distinguish confirmed findings from hypotheses and agree the scope before making changes.'], ['Which cities do you work in?','Builders and developers across India. The campaign is built for your city, locality and project.'],['Do you work with plotted, township or commercial projects?','Yes, the approach is the same: separate the buyers from everyone else, then measure every enquiry.']].map(([q,a])=><details key={q} className="group py-5"><summary className="flex cursor-pointer list-none items-center justify-between gap-6 text-base font-medium text-white/90 marker:content-none"><span>{q}</span><span className="text-xl text-[#E8282B] transition group-open:rotate-45">+</span></summary><p className="max-w-3xl pt-4 text-sm leading-7 text-white/55">{a}</p></details>)}</div></div></section>
    <section data-motion-reveal id="project-enquiry" className="relative scroll-mt-20 overflow-hidden" aria-labelledby="final-cta-title"><div className="pointer-events-none absolute -left-48 top-10 h-96 w-96 rounded-full bg-[#E8282B]/[.08] blur-3xl"/><div className="relative mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8 lg:py-24"><div className="max-w-3xl"><p className="text-[10px] font-semibold uppercase tracking-[.22em] text-[#E8282B]">Talk through your project</p><h2 id="final-cta-title" className="mt-4 text-3xl font-semibold leading-tight tracking-[-.035em] sm:text-4xl">Let's talk about your next launch</h2><p className="mt-4 leading-7 text-white/60">Discuss your project, buyer-search intent, target locations, tracking and the scope that makes sense for your goals. No fixed package is assumed before I understand the requirements.</p><div className="mt-6 flex flex-col gap-3 sm:flex-row sm:flex-wrap">{primary('final_cta','Book a free project strategy call',primaryClass)}{whatsappCta('final_cta','Discuss your project on WhatsApp',secondaryClass)}</div></div><div className="mt-12 grid gap-8 lg:grid-cols-[.7fr_1.3fr] lg:gap-14"><div><h3 className="text-xl font-semibold">Prefer to be contacted? Leave your details</h3><p className="mt-3 text-sm leading-6 text-white/55">Choose whether you want to discuss the project, request the free buyer-search map, or do both. There is no need to write a separate note.</p></div><form onSubmit={submitLead} onFocusCapture={handleFormFocus} className="rounded-2xl border border-white/10 bg-[#141414] p-5 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><Field label="Name *"><input required name="name" autoComplete="name" maxLength={120} value={name} onChange={e=>setName(e.target.value)} className="mt-2 w-full rounded-xl border border-white/10 bg-[#0D0D0D] px-4 py-3.5 text-sm text-white outline-none placeholder:text-white/25 focus:border-[#E8282B]/70" placeholder="Your name"/></Field><Field label="Company / project *"><input required name="company" autoComplete="organization" maxLength={180} value={company} onChange={e=>setCompany(e.target.value)} className="mt-2 w-full rounded-xl border border-white/10 bg-[#0D0D0D] px-4 py-3.5 text-sm text-white outline-none placeholder:text-white/25 focus:border-[#E8282B]/70" placeholder="Company or project name"/></Field><Field label="City *"><input required name="city" list="builder-city-suggestions" value={city} onChange={e=>setCity(e.target.value)} maxLength={80} autoComplete="address-level2" className="mt-2 w-full rounded-xl border border-white/10 bg-[#0D0D0D] px-4 py-3.5 text-sm text-white outline-none placeholder:text-white/25 focus:border-[#E8282B]/70" placeholder="Enter your city"/><datalist id="builder-city-suggestions">{CITY_SUGGESTIONS.map(option=><option key={option} value={option}/>)}</datalist></Field><Field label="WhatsApp *"><input required name="whatsapp" type="tel" autoComplete="tel" maxLength={40} value={whatsapp} onChange={e=>setWhatsapp(e.target.value)} className="mt-2 w-full rounded-xl border border-white/10 bg-[#0D0D0D] px-4 py-3.5 text-sm text-white outline-none placeholder:text-white/25 focus:border-[#E8282B]/70" placeholder="+91 …"/></Field><Field label="What would you like? *"><select required name="requestType" value={requestType} onChange={e=>setRequestType(e.target.value)} className="mt-2 w-full rounded-xl border border-white/10 bg-[#0D0D0D] px-4 py-3.5 text-sm text-white outline-none focus:border-[#E8282B]/70"><option value="both">Strategy call + free buyer-search map</option><option value="call">Strategy call</option><option value="map">Free buyer-search map</option></select></Field><Field label="Project type (optional)"><select name="projectType" value={projectType} onChange={e=>setProjectType(e.target.value)} className="mt-2 w-full rounded-xl border border-white/10 bg-[#0D0D0D] px-4 py-3.5 text-sm text-white outline-none focus:border-[#E8282B]/70"><option value="">Select project type</option>{PROJECT_TYPES.map(option=><option key={option} value={option}>{option}</option>)}</select></Field></div><div className="absolute -left-[10000px] top-auto h-px w-px overflow-hidden" aria-hidden="true"><label>Leave this field empty<input tabIndex={-1} autoComplete="off" name="hp" value={undefined} onChange={()=>{}}/></label></div><label className="mt-6 flex cursor-pointer items-start gap-3 text-xs leading-5 text-white/50"><input required type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)} className="mt-1 h-4 w-4 accent-[#E8282B]"/><span>I agree that R.K Digital Media may contact me about this enquiry.</span></label>{error && <div role="alert" className="mt-4 rounded-xl border border-red-500/25 bg-red-500/[.06] p-4"><p className="text-sm text-red-200">{error}</p><a href={waHref} onClick={()=>trackWhatsApp('form_error_fallback')} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-2 text-sm font-semibold text-white underline underline-offset-4">Continue on WhatsApp <Arrow className="h-4 w-4"/></a></div>}<button type="submit" disabled={submitting} className="mt-6 inline-flex w-full items-center justify-center gap-3 rounded-full bg-[#E8282B] px-6 py-4 text-sm font-bold text-white transition hover:bg-[#D02225] disabled:cursor-wait disabled:opacity-60 sm:w-auto">{submitting?'Sending request…':'Send project details'}<Arrow className="h-4 w-4"/></button><p className="mt-4 text-[10px] leading-5 text-white/35">Your details are used to respond to this enquiry.</p></form></div></div></section>
    <footer className="border-t border-white/10 bg-[#0D0D0D]"><div className="mx-auto flex max-w-7xl flex-col gap-4 px-4 py-8 text-xs text-white/40 sm:flex-row sm:items-center sm:justify-between sm:px-6 lg:px-8"><p>© {new Date().getFullYear()} R.K Digital Media. Google Ads for real estate builders and developers.</p><div className="flex flex-wrap gap-5"><Link href="/privacy-policy" className="transition hover:text-white/70">Privacy</Link><Link href="/services/google-ads" className="transition hover:text-white/70">Google Ads services</Link><Link href="/contact" className="transition hover:text-white/70">Contact</Link></div></div></footer>
    {stickyVisible && <div className="fixed inset-x-0 bottom-0 z-50 border-t border-white/10 bg-[#0D0D0D]/95 p-3 shadow-2xl backdrop-blur sm:hidden"><div className="mx-auto flex max-w-lg gap-2">{primary('sticky_mobile','Book a call','flex-1 inline-flex items-center justify-center gap-2 rounded-full bg-[#E8282B] px-4 py-3 text-sm font-bold text-white')}{whatsappCta('sticky_mobile','WhatsApp','inline-flex items-center justify-center rounded-full border border-white/20 px-4 py-3 text-sm font-semibold text-white')}</div></div>}
  </main>;
}

function FeatureIcon({ kind }: { kind: string }) {
  const paths: Record<string, ReactNode> = {
    target: <><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v2M22 12h-2M12 22v-2M2 12h2"/></>,
    map: <><path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15M15 6v15"/></>,
    page: <><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/></>,
    chart: <><path d="M4 19V5M4 19h17"/><path d="m7 15 4-4 3 2 5-7"/></>,
    report: <><path d="M5 3h11l3 3v15H5z"/><path d="M16 3v4h4M8 11h8M8 15h8"/></>,
  };
  return <svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[kind] || paths.target}</svg>;
}

